# ! [doc = " Useful synchronization primitives."] # ! [doc = ""] # ! [doc = " ## The need for synchronization"] # ! [doc = ""] # ! [doc = " Conceptually, a Rust program is a series of operations which will"] # ! [doc = " be executed on a computer. The timeline of events happening in the"] # ! [doc = " program is consistent with the order of the operations in the code."] # ! [doc = ""] # ! [doc = " Consider the following code, operating on some global static variables:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " // FIXME(static_mut_refs): Do not allow `static_mut_refs` lint"] # ! [doc = " #![allow(static_mut_refs)]"] # ! [doc = ""] # ! [doc = " static mut A: u32 = 0;"] # ! [doc = " static mut B: u32 = 0;"] # ! [doc = " static mut C: u32 = 0;"] # ! [doc = ""] # ! [doc = " fn main() {"] # ! [doc = "     unsafe {"] # ! [doc = "         A = 3;"] # ! [doc = "         B = 4;"] # ! [doc = "         A = A + B;"] # ! [doc = "         C = B;"] # ! [doc = "         println!(\"{A} {B} {C}\");"] # ! [doc = "         C = A;"] # ! [doc = "     }"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " It appears as if some variables stored in memory are changed, an addition"] # ! [doc = " is performed, result is stored in `A` and the variable `C` is"] # ! [doc = " modified twice."] # ! [doc = ""] # ! [doc = " When only a single thread is involved, the results are as expected:"] # ! [doc = " the line `7 4 4` gets printed."] # ! [doc = ""] # ! [doc = " As for what happens behind the scenes, when optimizations are enabled the"] # ! [doc = " final generated machine code might look very different from the code:"] # ! [doc = ""] # ! [doc = " - The first store to `C` might be moved before the store to `A` or `B`,"] # ! [doc = "   _as if_ we had written `C = 4; A = 3; B = 4`."] # ! [doc = ""] # ! [doc = " - Assignment of `A + B` to `A` might be removed, since the sum can be stored"] # ! [doc = "   in a temporary location until it gets printed, with the global variable"] # ! [doc = "   never getting updated."] # ! [doc = ""] # ! [doc = " - The final result could be determined just by looking at the code"] # ! [doc = "   at compile time, so [constant folding] might turn the whole"] # ! [doc = "   block into a simple `println!(\"7 4 4\")`."] # ! [doc = ""] # ! [doc = " The compiler is allowed to perform any combination of these"] # ! [doc = " optimizations, as long as the final optimized code, when executed,"] # ! [doc = " produces the same results as the one without optimizations."] # ! [doc = ""] # ! [doc = " Due to the [concurrency] involved in modern computers, assumptions"] # ! [doc = " about the program's execution order are often wrong. Access to"] # ! [doc = " global variables can lead to nondeterministic results, **even if**"] # ! [doc = " compiler optimizations are disabled, and it is **still possible**"] # ! [doc = " to introduce synchronization bugs."] # ! [doc = ""] # ! [doc = " Note that thanks to Rust's safety guarantees, accessing global (static)"] # ! [doc = " variables requires `unsafe` code, assuming we don't use any of the"] # ! [doc = " synchronization primitives in this module."] # ! [doc = ""] # ! [doc = " [constant folding]: https://en.wikipedia.org/wiki/Constant_folding"] # ! [doc = " [concurrency]: https://en.wikipedia.org/wiki/Concurrency_(computer_science)"] # ! [doc = ""] # ! [doc = " ## Out-of-order execution"] # ! [doc = ""] # ! [doc = " Instructions can execute in a different order from the one we define, due to"] # ! [doc = " various reasons:"] # ! [doc = ""] # ! [doc = " - The **compiler** reordering instructions: If the compiler can issue an"] # ! [doc = "   instruction at an earlier point, it will try to do so. For example, it"] # ! [doc = "   might hoist memory loads at the top of a code block, so that the CPU can"] # ! [doc = "   start [prefetching] the values from memory."] # ! [doc = ""] # ! [doc = "   In single-threaded scenarios, this can cause issues when writing"] # ! [doc = "   signal handlers or certain kinds of low-level code."] # ! [doc = "   Use [compiler fences] to prevent this reordering."] # ! [doc = ""] # ! [doc = " - A **single processor** executing instructions [out-of-order]:"] # ! [doc = "   Modern CPUs are capable of [superscalar] execution,"] # ! [doc = "   i.e., multiple instructions might be executing at the same time,"] # ! [doc = "   even though the machine code describes a sequential process."] # ! [doc = ""] # ! [doc = "   This kind of reordering is handled transparently by the CPU."] # ! [doc = ""] # ! [doc = " - A **multiprocessor** system executing multiple hardware threads"] # ! [doc = "   at the same time: In multi-threaded scenarios, you can use two"] # ! [doc = "   kinds of primitives to deal with synchronization:"] # ! [doc = "   - [memory fences] to ensure memory accesses are made visible to"] # ! [doc = "   other CPUs in the right order."] # ! [doc = "   - [atomic operations] to ensure simultaneous access to the same"] # ! [doc = "   memory location doesn't lead to undefined behavior."] # ! [doc = ""] # ! [doc = " [prefetching]: https://en.wikipedia.org/wiki/Cache_prefetching"] # ! [doc = " [compiler fences]: crate::sync::atomic::compiler_fence"] # ! [doc = " [out-of-order]: https://en.wikipedia.org/wiki/Out-of-order_execution"] # ! [doc = " [superscalar]: https://en.wikipedia.org/wiki/Superscalar_processor"] # ! [doc = " [memory fences]: crate::sync::atomic::fence"] # ! [doc = " [atomic operations]: crate::sync::atomic"] # ! [doc = ""] # ! [doc = " ## Higher-level synchronization objects"] # ! [doc = ""] # ! [doc = " Most of the low-level synchronization primitives are quite error-prone and"] # ! [doc = " inconvenient to use, which is why the standard library also exposes some"] # ! [doc = " higher-level synchronization objects."] # ! [doc = ""] # ! [doc = " These abstractions can be built out of lower-level primitives."] # ! [doc = " For efficiency, the sync objects in the standard library are usually"] # ! [doc = " implemented with help from the operating system's kernel, which is"] # ! [doc = " able to reschedule the threads while they are blocked on acquiring"] # ! [doc = " a lock."] # ! [doc = ""] # ! [doc = " The following is an overview of the available synchronization"] # ! [doc = " objects:"] # ! [doc = ""] # ! [doc = " - [`Arc`]: Atomically Reference-Counted pointer, which can be used"] # ! [doc = "   in multithreaded environments to prolong the lifetime of some"] # ! [doc = "   data until all the threads have finished using it."] # ! [doc = ""] # ! [doc = " - [`Barrier`]: Ensures multiple threads will wait for each other"] # ! [doc = "   to reach a point in the program, before continuing execution all"] # ! [doc = "   together."] # ! [doc = ""] # ! [doc = " - [`Condvar`]: Condition Variable, providing the ability to block"] # ! [doc = "   a thread while waiting for an event to occur."] # ! [doc = ""] # ! [doc = " - [`mpsc`]: Multi-producer, single-consumer queues, used for"] # ! [doc = "   message-based communication. Can provide a lightweight"] # ! [doc = "   inter-thread synchronisation mechanism, at the cost of some"] # ! [doc = "   extra memory."] # ! [doc = ""] # ! [doc = " - [`mpmc`]: Multi-producer, multi-consumer queues, used for"] # ! [doc = "   message-based communication. Can provide a lightweight"] # ! [doc = "   inter-thread synchronisation mechanism, at the cost of some"] # ! [doc = "   extra memory."] # ! [doc = ""] # ! [doc = " - [`Mutex`]: Mutual Exclusion mechanism, which ensures that at"] # ! [doc = "   most one thread at a time is able to access some data."] # ! [doc = ""] # ! [doc = " - [`Once`]: Used for a thread-safe, one-time global initialization routine."] # ! [doc = "   Mostly useful for implementing other types like `OnceLock`."] # ! [doc = ""] # ! [doc = " - [`OnceLock`]: Used for thread-safe, one-time initialization of a"] # ! [doc = "   variable, with potentially different initializers based on the caller."] # ! [doc = ""] # ! [doc = " - [`LazyLock`]: Used for thread-safe, one-time initialization of a"] # ! [doc = "   variable, using one nullary initializer function provided at creation."] # ! [doc = ""] # ! [doc = " - [`RwLock`]: Provides a mutual exclusion mechanism which allows"] # ! [doc = "   multiple readers at the same time, while allowing only one"] # ! [doc = "   writer at a time. In some cases, this can be more efficient than"] # ! [doc = "   a mutex."] # ! [doc = ""] # ! [doc = " [`Arc`]: crate::sync::Arc"] # ! [doc = " [`Barrier`]: crate::sync::Barrier"] # ! [doc = " [`Condvar`]: crate::sync::Condvar"] # ! [doc = " [`mpmc`]: crate::sync::mpmc"] # ! [doc = " [`mpsc`]: crate::sync::mpsc"] # ! [doc = " [`Mutex`]: crate::sync::Mutex"] # ! [doc = " [`Once`]: crate::sync::Once"] # ! [doc = " [`OnceLock`]: crate::sync::OnceLock"] # ! [doc = " [`RwLock`]: crate::sync::RwLock"] # ! [stable (feature = "rust1" , since = "1.0.0")] # ! [cfg_attr (rustfmt , rustfmt :: skip)] use split_decls_genesis :: ourprelude :: * ; #[unstable (feature = "exclusive_wrapper" , issue = "98407")] pub use core :: sync :: Exclusive ; #[stable (feature = "rust1" , since = "1.0.0")] pub use core :: sync :: atomic ; #[unstable (feature = "unique_rc_arc" , issue = "112566")] pub use alloc_crate :: sync :: UniqueArc ; #[stable (feature = "rust1" , since = "1.0.0")] pub use alloc_crate :: sync :: { Arc , Weak } ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: barrier :: { Barrier , BarrierWaitResult } ; #[stable (feature = "lazy_cell" , since = "1.80.0")] pub use self :: lazy_lock :: LazyLock ; #[stable (feature = "once_cell" , since = "1.70.0")] pub use self :: once_lock :: OnceLock ; #[unstable (feature = "reentrant_lock" , issue = "121440")] pub use self :: reentrant_lock :: { ReentrantLock , ReentrantLockGuard } ; #[stable (feature = "rust1" , since = "1.0.0")] #[doc (inline)] pub use self :: poison :: { LockResult , PoisonError } ; #[stable (feature = "rust1" , since = "1.0.0")] #[doc (inline)] pub use self :: poison :: { Mutex , MutexGuard , TryLockError , TryLockResult , Condvar , Once , OnceState , RwLock , RwLockReadGuard , RwLockWriteGuard , } ; #[stable (feature = "rust1" , since = "1.0.0")] #[doc (inline)] #[expect (deprecated)] pub use self :: poison :: ONCE_INIT ; #[unstable (feature = "mapped_lock_guards" , issue = "117108")] #[doc (inline)] pub use self :: poison :: { MappedMutexGuard , MappedRwLockReadGuard , MappedRwLockWriteGuard } ; #[unstable (feature = "mpmc_channel" , issue = "126840")] pub mod mpmc ; pub mod mpsc ; #[unstable (feature = "sync_nonpoison" , issue = "134645")] pub mod nonpoison ; #[unstable (feature = "sync_poison_mod" , issue = "134646")] pub mod poison ; mod barrier ; mod lazy_lock ; mod once_lock ; mod reentrant_lock ; #[doc = " A type indicating whether a timed wait on a condition variable returned"] #[doc = " due to a time out or not."] #[doc = ""] #[doc = " It is returned by the [`wait_timeout`] method."] #[doc = ""] #[doc = " [`wait_timeout`]: Condvar::wait_timeout"] #[derive (Debug , PartialEq , Eq , Copy , Clone)] #[stable (feature = "wait_timeout" , since = "1.5.0")] pub struct WaitTimeoutResult (bool) ; impl WaitTimeoutResult { #[doc = " Returns `true` if the wait was known to have timed out."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " This example spawns a thread which will sleep 20 milliseconds before"] #[doc = " updating a boolean value and then notifying the condvar."] #[doc = ""] #[doc = " The main thread will wait with a 10 millisecond timeout on the condvar"] #[doc = " and will leave the loop upon timeout."] #[doc = ""] #[doc = " ```"] #[doc = " use std::sync::{Arc, Condvar, Mutex};"] #[doc = " use std::thread;"] #[doc = " use std::time::Duration;"] #[doc = ""] #[doc = " let pair = Arc::new((Mutex::new(false), Condvar::new()));"] #[doc = " let pair2 = Arc::clone(&pair);"] #[doc = ""] #[doc = " # let handle ="] #[doc = " thread::spawn(move || {"] #[doc = "     let (lock, cvar) = &*pair2;"] #[doc = ""] #[doc = "     // Let's wait 20 milliseconds before notifying the condvar."] #[doc = "     thread::sleep(Duration::from_millis(20));"] #[doc = ""] #[doc = "     let mut started = lock.lock().unwrap();"] #[doc = "     // We update the boolean value."] #[doc = "     *started = true;"] #[doc = "     cvar.notify_one();"] #[doc = " });"] #[doc = ""] #[doc = " // Wait for the thread to start up."] #[doc = " let (lock, cvar) = &*pair;"] #[doc = " loop {"] #[doc = "     // Let's put a timeout on the condvar's wait."] #[doc = "     let result = cvar.wait_timeout(lock.lock().unwrap(), Duration::from_millis(10)).unwrap();"] #[doc = "     // 10 milliseconds have passed."] #[doc = "     if result.1.timed_out() {"] #[doc = "         // timed out now and we can leave."] #[doc = "         break"] #[doc = "     }"] #[doc = " }"] #[doc = " # // Prevent leaks for Miri."] #[doc = " # let _ = handle.join();"] #[doc = " ```"] #[must_use] #[stable (feature = "wait_timeout" , since = "1.5.0")] pub fn timed_out (& self) -> bool { self . 0 } }